    :param product: Variable product and variants information
    :return: list of term names
    """
def get_attribute_terms(product: Any) -> object {
    attribute_terms = `list();
    for variation in product['variants'] {
        if (variation['option_1_value'] not in attribute_terms) {
            attribute_terms.append(variation['option_1_value']);
        }
    }
    return attribute_terms;
}

"""Returns whether or not a given module can be imported."""
def has_module(module_name: Any, members: Any = []) -> object {
    try {
        mod = __import__(module_name, fromlist=members);
    } except ImportError {
        return False;
    }
    for member in members {
        if not hasattr(mod, member) {
            return False;
        }
    }
    return True;
}

